const rows = $json.results || [];

let question = "";
try {
  question = $("Build Quality Query").first().json.question || "";
} catch (e) {
  question = "";
}

const qualityItems = rows.map((row) => ({
  item_id: row.item_id || null,
  item_type: row.item_type || null,
  item_name: row.item_name || null,
  properties: row.properties || {},
  relationship: row.relationship || null,
  connected_labels: row.connected_labels || [],
  connected_entity: row.connected_entity || null,
}));

return [
  {
    json: {
      agent: "quality_analyst",
      domain: "Quality Analyst",
      status: "data_retrieved",
      question,
      evidenceLabel: "qualityItems",
      evidenceData: qualityItems,
      rawResult: $json,
    },
  },
];

const agent = $json.agent || "quality_analyst";
const domain = $json.domain || "Quality Analyst";
const question = $json.question || "";
const evidenceLabel = $json.evidenceLabel || "qualityItems";
const evidenceData = $json.evidenceData || [];
const rawResult = $json.rawResult || {};

const systemPrompt = `
You are a Quality Analyst Agent for a supply chain knowledge graph.

Your job:
- Analyze test reports, audit findings, incident reports, maintenance events, defects, failures, and inspection-related graph data.
- Identify quality problems, recurring failure patterns, affected entities, and potential root causes.
- Explain the operational and customer impact clearly.
- Give practical quality improvement recommendations.
- Do not invent facts.
- If graph data is limited or missing quality fields, clearly say that.

Return ONLY valid JSON.
`;

const userPrompt = `
User question:
${question}

Quality evidence:
${JSON.stringify(evidenceData, null, 2)}

Raw graph result:
${JSON.stringify(rawResult, null, 2)}

Return JSON with this exact schema:
{
  "answer": "string",
  "keyFindings": ["string"],
  "qualityInsights": [
    {
      "id": "string",
      "type": "string",
      "name": "string",
      "qualityIssue": "string",
      "severity": "low | medium | high | unknown",
      "insight": "string"
    }
  ],
  "affectedEntities": [
    {
      "entity": "string",
      "relationship": "string",
      "impact": "string"
    }
  ],
  "recommendations": ["string"],
  "confidence": "low | medium | high"
}
`;

return [
  {
    json: {
      agent,
      domain,
      question,
      evidenceLabel,
      evidenceData,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: systemPrompt,
          },
          {
            role: "user",
            content: userPrompt,
          },
        ],
        temperature: 0.2,
        max_tokens: 2048,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The quality analyst could not generate a summary.",
    keyFindings: [],
    qualityInsights: [],
    affectedEntities: [],
    recommendations: [],
    confidence: "low",
  };
}

let context = {};
try {
  context = $("Build LLM Summary Payload").first().json;
} catch (e) {
  context = {};
}

return [
  {
    json: {
      agent: "quality_analyst",
      domain: "Quality Analyst",
      status: "completed",
      question: context.question || "",
      answer: parsed.answer || "",
      keyFindings: parsed.keyFindings || [],
      qualityInsights: parsed.qualityInsights || [],
      affectedEntities: parsed.affectedEntities || [],
      recommendations: parsed.recommendations || [],
      confidence: parsed.confidence || "medium",
      evidence: {
        qualityItems: context.evidenceData || [],
      },
      rawLlmOutput: parsed,
    },
  },
];

const selectedAgents = $json.selectedAgents || [];

const shouldRun =
  selectedAgents.includes("quality_analyst") ||
  selectedAgents.includes("all");

return [
  {
    json: {
      ...$json,
      shouldRun,
    },
  },
];

return [
  {
    json: {
      agent: "quality_analyst",
      domain: "Quality Analyst",
      status: "skipped",
      question: $json.question || "",
      answer: "",
      keyFindings: [],
      qualityInsights: [],
      affectedEntities: [],
      recommendations: [],
      confidence: "not_applicable",
      evidence: {},
    },
  },
];
